"""Standard-library HTTP front end for :class:`ContentAddressedStore`.

Every failure is a single-line JSON body ``{"error": "..."}`` with status 400,
404, 405, 409, 411, 412 or 500 (500 for a corrupted blob or a blob/upload I/O
error).
"""

from __future__ import annotations

import json
import re
import sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, unquote, urlparse

from .store import (
    DEFAULT_LIMIT,
    ContentAddressedStore,
    ObjectStoreError,
    SessionConflict,
    _MISSING,
)

__all__ = ["ObjectStoreHandler", "ObjectStoreHTTPServer", "create_server"]

_SHA256_RE = re.compile(r"\A[0-9a-f]{64}\Z")
_ETAG_RE = re.compile(r'\A"([0-9a-f]{64})"\Z')
_OBJECTS_PATH = "/v1/objects"
_BLOBS_PATH = "/v1/blobs"
_UPLOADS_PATH = "/v1/uploads"
_DEFAULT_CONTENT_TYPE = "application/octet-stream"
_DECIMAL_RE = re.compile(r"\A[0-9]+\Z")
_BAD_REQUEST_PREFIXES = (
    "invalid sha256", "invalid limit", "invalid key", "invalid prefix",
    "invalid after", "invalid size", "invalid offset", "invalid json",
    "invalid precondition", "payload", "content_type",
)
_INTERNAL_ERRORS = ("corrupted blob", "blob io error", "upload io error")


def _json_bytes(payload):
    return json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")


def _status_for(message):
    if message in _INTERNAL_ERRORS:
        return 500
    if message == "precondition failed":
        return 412
    for prefix in _BAD_REQUEST_PREFIXES:
        if message.startswith(prefix):
            return 400
    return 404


class ObjectStoreHandler(BaseHTTPRequestHandler):
    """Routes the object-store REST surface onto a ContentAddressedStore."""

    server_version = "objstore/0.1"
    sys_version = ""
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):
        sys.stderr.write("%s - %s\n" % (self.address_string(), fmt % args))

    def _send(self, status, body, content_type="application/json", extra_headers=(),
              head_only=False, length=None):
        self.send_response(status)
        if status != 204:
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(body) if length is None else length))
        for name, value in extra_headers:
            self.send_header(name, value)
        self.end_headers()
        if body and not head_only and status != 204:
            self.wfile.write(body)

    def _error(self, status, message, close=False):
        extra = [("Connection", "close")] if close else ()
        if close:
            self.close_connection = True
        self._send(status, _json_bytes({"error": message}), extra_headers=extra)

    def _read_body(self):
        raw = self.headers.get("Content-Length")
        try:
            length = int(raw)
        except (TypeError, ValueError):
            return None
        if length < 0:
            return None
        return self.rfile.read(length) if length else b""

    def _precondition_headers(self):
        """Map If-Match / If-None-Match onto an ``expected_sha256`` argument.

        Returns the omitted sentinel when no condition is present, ``None``
        for ``If-None-Match: *`` (key must be absent), or the 64 hex digits
        of a single double-quoted ``If-Match`` digest. Both headers at once,
        a repeated header, or any other syntax is an ``invalid precondition``
        error.
        """
        if_match = self.headers.get_all("If-Match") or []
        if_none = self.headers.get_all("If-None-Match") or []
        if len(if_match) > 1 or len(if_none) > 1 or (if_match and if_none):
            raise ObjectStoreError("invalid precondition")
        if if_match:
            match = _ETAG_RE.match(if_match[0])
            if match is None:
                raise ObjectStoreError("invalid precondition")
            return match.group(1)
        if if_none:
            if if_none[0] != "*":
                raise ObjectStoreError("invalid precondition")
            return None
        return _MISSING

    @staticmethod
    def _etag_headers(entry):
        return [("X-Content-Sha256", entry["sha256"]),
                ("ETag", '"%s"' % entry["sha256"])]

    def do_GET(self):
        self._dispatch("GET")

    def do_HEAD(self):
        self._dispatch("HEAD")

    def do_POST(self):
        self._dispatch("POST")

    def do_PUT(self):
        self._dispatch("PUT")

    def do_DELETE(self):
        self._dispatch("DELETE")

    def _dispatch(self, method):
        parsed = urlparse(self.path)
        path = parsed.path
        try:
            if path == "/healthz":
                if method != "GET":
                    return self._error(405, "method not allowed")
                return self._send(200, _json_bytes({"ok": True}))
            if path == _OBJECTS_PATH:
                if method != "GET":
                    return self._error(405, "method not allowed")
                return self._list(parsed.query)
            if path.startswith(_OBJECTS_PATH + "/"):
                return self._object(method, unquote(path[len(_OBJECTS_PATH) + 1:]))
            if path == _UPLOADS_PATH:
                if self.headers.get("Transfer-Encoding") is not None:
                    self.close_connection = True
                    return self._error(400, "transfer encoding not supported")
                if method != "POST":
                    return self._error(405, "method not allowed")
                return self._create_upload()
            if path.startswith(_UPLOADS_PATH + "/"):
                return self._upload_session(
                    method, unquote(path[len(_UPLOADS_PATH) + 1:]), parsed.query)
            if path.startswith(_BLOBS_PATH + "/"):
                if method != "GET":
                    return self._error(405, "method not allowed")
                return self._blob(unquote(path[len(_BLOBS_PATH) + 1:]))
            return self._error(404, "not found")
        except SessionConflict as exc:
            return self._error(409, str(exc))
        except ObjectStoreError as exc:
            return self._error(_status_for(str(exc)), str(exc))
        except (BrokenPipeError, ConnectionResetError):
            return None

    def _object(self, method, key):
        if not key:
            return self._error(400, "invalid key")
        store = self.server.store
        if method == "PUT":
            body = self._read_body()
            if body is None:
                return self._error(411, "length required")
            ContentAddressedStore._check_key(key)
            expected = self._precondition_headers()
            try:
                existing = store.head(key)
            except ObjectStoreError:
                existing = None
            entry = store.put(key, body, content_type=self.headers.get("Content-Type"),
                              expected_sha256=expected)
            repeated = existing is not None and existing["sha256"] == entry["sha256"]
            body_out = {"key": key, "sha256": entry["sha256"], "size": entry["size"]}
            return self._send(200 if repeated else 201, _json_bytes(body_out))
        if method == "GET":
            data, entry = store.get(key)
            return self._send(200, data, entry["content_type"] or _DEFAULT_CONTENT_TYPE,
                              self._etag_headers(entry))
        if method == "HEAD":
            entry = store.head(key)
            return self._send(200, b"", entry["content_type"] or _DEFAULT_CONTENT_TYPE,
                              self._etag_headers(entry), head_only=True,
                              length=entry["size"])
        if method == "DELETE":
            ContentAddressedStore._check_key(key)
            expected = self._precondition_headers()
            store.delete(key, expected_sha256=expected)
            return self._send(204, b"")
        return self._error(405, "method not allowed")

    # -- resumable upload sessions -------------------------------------
    def _read_length_body(self):
        """Read a body framed strictly by Content-Length.

        Transfer-Encoding wins over every other problem (400); a missing,
        non-integer or negative Content-Length is 411; a body that ends
        before the declared length is 400. Returns ``(body, (status,
        message))`` with the error element ``None`` on success.
        """
        if self.headers.get("Transfer-Encoding") is not None:
            self.close_connection = True
            return None, (400, "transfer encoding not supported")
        raw = self.headers.get("Content-Length")
        if raw is None or _DECIMAL_RE.match(raw) is None:
            self.close_connection = True
            return None, (411, "length required")
        length = int(raw)
        body = self.rfile.read(length) if length else b""
        if len(body) != length:
            self.close_connection = True
            return None, (400, "truncated request body")
        return body, None

    @staticmethod
    def _json_object(body):
        """Decode *body* as a UTF-8 JSON object or raise a 400-class error."""
        try:
            text = body.decode("utf-8")
        except UnicodeDecodeError:
            raise ObjectStoreError("invalid json: body is not utf-8")
        try:
            document = json.loads(text)
        except ValueError:
            raise ObjectStoreError("invalid json: body is not a json document")
        if not isinstance(document, dict):
            raise ObjectStoreError("invalid json: body must be a json object")
        return document

    @staticmethod
    def _offset_param(query):
        """Return the unique non-negative decimal ``offset`` query value."""
        params = parse_qs(query, keep_blank_values=True)
        values = params.get("offset")
        if values is None or len(values) != 1 or _DECIMAL_RE.match(values[0]) is None:
            raise ObjectStoreError("invalid offset")
        return int(values[0])

    def _create_upload(self):
        body, error = self._read_length_body()
        if error is not None:
            return self._error(*error)
        document = self._json_object(body)
        allowed = {"key", "size", "sha256", "content_type"}
        unknown = set(document) - allowed
        if unknown:
            raise ObjectStoreError("invalid json: unknown field %r" % (sorted(unknown)[0],))
        missing = [name for name in ("key", "size", "sha256") if name not in document]
        if missing:
            raise ObjectStoreError("invalid json: missing field %r" % (missing[0],))
        content_type = document.get("content_type")
        # Validate every body value before touching the conditional headers:
        # request/body errors keep precedence over precondition errors.
        key, size, digest = document["key"], document["size"], document["sha256"]
        ContentAddressedStore._check_key(key)
        if isinstance(size, bool) or not isinstance(size, int) or size < 0:
            raise ObjectStoreError("invalid size: %r" % (size,))
        ContentAddressedStore._require_sha(digest)
        if content_type is not None and not isinstance(content_type, str):
            raise ObjectStoreError("content_type must be a string or None")
        expected = self._precondition_headers()
        session_id = self.server.store.begin_upload(
            key, size, digest, content_type=content_type,
            expected_sha256=expected)
        return self._send(201, _json_bytes({"session": session_id}))

    def _upload_session(self, method, tail, query):
        # Transfer-Encoding is rejected before method/session validation.
        if self.headers.get("Transfer-Encoding") is not None:
            self.close_connection = True
            return self._error(400, "transfer encoding not supported")
        session_id, sep, sub = tail.partition("/")
        if not session_id:
            return self._error(404, "not found")
        if not sep:
            return self._upload_session_item(method, session_id, query)
        if sub == "complete":
            if method != "POST":
                return self._error(405, "method not allowed")
            return self._complete_upload(session_id)
        return self._error(404, "not found")

    def _upload_session_item(self, method, session_id, query):
        store = self.server.store
        if method == "GET":
            return self._send(200, _json_bytes(store.upload_status(session_id)))
        if method == "DELETE":
            store.abort_upload(session_id)
            return self._send(204, b"")
        if method != "PUT":
            return self._error(405, "method not allowed")
        body, error = self._read_length_body()
        if error is not None:
            return self._error(*error)
        offset = self._offset_param(query)
        confirmed = store.append_upload(session_id, offset, body)
        return self._send(200, _json_bytes({"offset": confirmed}))

    def _complete_upload(self, session_id):
        # No body is required, but framing headers still have to be sane and
        # any declared bytes are drained so the connection can be reused.
        if self.headers.get("Transfer-Encoding") is not None:
            self.close_connection = True
            return self._error(400, "transfer encoding not supported")
        raw = self.headers.get("Content-Length")
        if raw is not None:
            if _DECIMAL_RE.match(raw) is None:
                self.close_connection = True
                return self._error(400, "invalid content length")
            length = int(raw)
            if length:
                drained = self.rfile.read(length)
                if len(drained) != length:
                    self.close_connection = True
                    return self._error(400, "truncated request body")
        entry = self.server.store.complete_upload(session_id)
        return self._send(200, _json_bytes(entry))

    def _list(self, query):
        params = parse_qs(query, keep_blank_values=True)
        raw_limit = params.get("limit", [str(DEFAULT_LIMIT)])[0]
        try:
            limit = int(raw_limit)
        except (TypeError, ValueError):
            raise ObjectStoreError("invalid limit: %r" % (raw_limit,))
        result = self.server.store.list_objects(
            prefix=params.get("prefix", [""])[0],
            after=params.get("after", [None])[0] or None,
            limit=limit,
        )
        return self._send(200, _json_bytes(result))

    def _blob(self, sha256):
        if _SHA256_RE.match(sha256) is None:
            raise ObjectStoreError("invalid sha256: %r" % (sha256,))
        return self._send(200, self.server.store.blob(sha256), _DEFAULT_CONTENT_TYPE,
                          [("X-Content-Sha256", sha256)])


class ObjectStoreHTTPServer(ThreadingHTTPServer):
    """Threading HTTP server carrying a reference to the object store."""

    daemon_threads = True
    allow_reuse_address = True


def create_server(store, host="127.0.0.1", port=8080):
    """Bind a new HTTP server for *store*; port 0 picks an ephemeral port."""
    if not isinstance(store, ContentAddressedStore):
        raise ObjectStoreError("store must be a ContentAddressedStore")
    httpd = ObjectStoreHTTPServer((host, port), ObjectStoreHandler)
    httpd.store = store
    return httpd

"""Content-addressed object store (standard library only).

Blob bytes are stored once as ``<root>/blobs/<sha256>``; object metadata
(``key -> {sha256, size, content_type}``) lives in ``<root>/index.json`` and is
always rewritten through a temporary file plus ``os.replace``. Every mutation
and every consistent read runs under a single re-entrant lock.

Resumable uploads live under ``<root>/uploads/`` (created lazily): each
session is a ``<session>.json`` declaration plus confirmed offset and a
``<session>.part`` file holding the received bytes. Completing a session
publishes the object and records the result in the index's ``uploads`` map in
one atomic index rewrite, so the completion flag can never disagree with the
published object.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
import stat
import threading
import uuid

__all__ = ["ContentAddressedStore", "ObjectStoreError", "SessionConflict"]

INDEX_NAME = "index.json"
BLOBS_DIRNAME = "blobs"
UPLOADS_DIRNAME = "uploads"
INDEX_VERSION = 1
DEFAULT_LIMIT = 100
MAX_LIMIT = 1000

_SHA256_RE = re.compile(r"\A[0-9a-f]{64}\Z")
_SESSION_META_RE = re.compile(r"\A([0-9a-f]{32})\.json\Z")
_MISSING = object()


class ObjectStoreError(Exception):
    """Missing object, invalid key/digest/limit, or a corrupted index."""


class SessionConflict(ObjectStoreError):
    """An upload operation that violates the session's current state.

    A subclass of :class:`ObjectStoreError`, so existing callers keep
    catching it; front ends (HTTP) can nevertheless distinguish these
    state conflicts from bad input and report them separately.
    """


def _is_sha256(value):
    return isinstance(value, str) and _SHA256_RE.match(value) is not None


def _atomic_write(path, data):
    """Write *data* to *path* via a unique temp file plus os.replace."""
    tmp = "%s.tmp.%d.%d" % (path, os.getpid(), threading.get_ident())
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            try:
                os.remove(tmp)
            except OSError:
                pass


class ContentAddressedStore:
    """Multi-tenant key -> content-addressed blob mapping persisted on disk."""

    def __init__(self, root):
        if not isinstance(root, (str, bytes, os.PathLike)):
            raise ObjectStoreError("invalid root: %r" % (root,))
        self.root = os.path.abspath(os.fspath(root))
        self.blobs_dir = os.path.join(self.root, BLOBS_DIRNAME)
        self.uploads_dir = os.path.join(self.root, UPLOADS_DIRNAME)
        self.index_path = os.path.join(self.root, INDEX_NAME)
        self._lock = threading.RLock()
        os.makedirs(self.blobs_dir, exist_ok=True)
        self._index, self._upload_records = self._load_index()
        self._uploads = self._load_uploads()

    # -- index ---------------------------------------------------------
    def _load_index(self):
        if not os.path.exists(self.index_path):
            return {"version": INDEX_VERSION, "objects": {}}, {}
        try:
            with open(self.index_path, "rb") as handle:
                document = json.loads(handle.read().decode("utf-8"))
        except (OSError, ValueError, UnicodeDecodeError) as exc:
            raise ObjectStoreError("corrupted index: %s" % (exc,))
        if not isinstance(document, dict) or not isinstance(document.get("objects"), dict):
            raise ObjectStoreError("corrupted index: missing objects map")
        objects = {}
        for key, entry in document["objects"].items():
            if not isinstance(key, str):
                raise ObjectStoreError("corrupted index: non-string key")
            objects[key] = self._validate_entry(key, entry)
        records = {}
        raw_records = document.get("uploads", {})
        if not isinstance(raw_records, dict):
            raise ObjectStoreError("corrupted index: uploads is not a map")
        for session_id, record in raw_records.items():
            if not isinstance(session_id, str) or not isinstance(record, dict):
                raise ObjectStoreError("corrupted index: bad upload record")
            key = record.get("key")
            if not isinstance(key, str):
                raise ObjectStoreError("corrupted index: bad upload record")
            records[session_id] = {
                "key": key,
                "entry": self._validate_entry(key, record.get("entry")),
            }
        return {"version": INDEX_VERSION, "objects": objects}, records

    @staticmethod
    def _validate_entry(key, entry):
        if not isinstance(entry, dict):
            raise ObjectStoreError("corrupted index: entry for %r is not an object" % (key,))
        sha, size = entry.get("sha256"), entry.get("size")
        content_type = entry.get("content_type")
        if not _is_sha256(sha):
            raise ObjectStoreError("corrupted index: bad sha256 for %r" % (key,))
        if isinstance(size, bool) or not isinstance(size, int) or size < 0:
            raise ObjectStoreError("corrupted index: bad size for %r" % (key,))
        if content_type is not None and not isinstance(content_type, str):
            raise ObjectStoreError("corrupted index: bad content_type for %r" % (key,))
        return {"sha256": sha, "size": size, "content_type": content_type}

    def _save_index(self):
        document = {"version": INDEX_VERSION, "objects": self._index["objects"]}
        if self._upload_records:
            document["uploads"] = self._upload_records
        payload = json.dumps(document, sort_keys=True, separators=(",", ":"))
        _atomic_write(self.index_path, payload.encode("utf-8") + b"\n")

    # -- validation ----------------------------------------------------
    @staticmethod
    def _check_key(key):
        if not isinstance(key, str) or not key or "\x00" in key:
            raise ObjectStoreError("invalid key: %r" % (key,))
        if any(part in ("", ".", "..") for part in key.split("/")):
            raise ObjectStoreError("invalid key: %r" % (key,))
        return key

    @staticmethod
    def _check_limit(limit):
        if isinstance(limit, bool) or not isinstance(limit, int):
            raise ObjectStoreError("invalid limit: %r" % (limit,))
        if not 1 <= limit <= MAX_LIMIT:
            raise ObjectStoreError("invalid limit: %r" % (limit,))
        return limit

    @staticmethod
    def _require_sha(sha256):
        if not _is_sha256(sha256):
            raise ObjectStoreError("invalid sha256: %r" % (sha256,))
        return sha256

    @staticmethod
    def _check_precondition(expected_sha256):
        """Normalize an ``expected_sha256`` keyword argument.

        Omitted (the ``_MISSING`` sentinel) means no condition; an explicit
        ``None`` means the key must not exist; a 64-digit lowercase hex string
        means the key must exist with that exact digest. Anything else is an
        ``invalid precondition`` error rather than a failed condition.
        """
        if expected_sha256 is _MISSING:
            return _MISSING
        if expected_sha256 is None:
            return None
        if _is_sha256(expected_sha256):
            return expected_sha256
        raise ObjectStoreError("invalid precondition")

    def _precondition_met(self, key, expected):
        """Return whether *key* currently satisfies the *expected* condition."""
        entry = self._index["objects"].get(key)
        if expected is None:
            return entry is None
        return entry is not None and entry["sha256"] == expected

    # -- object API ----------------------------------------------------
    def put(self, key, payload, content_type=None, expected_sha256=_MISSING):
        """Store *payload* under *key* and return its metadata entry.

        *expected_sha256* is an atomic precondition on the key's current
        digest: omitted leaves the old overwrite behaviour, an explicit
        ``None`` requires the key not to exist, and a 64 lowercase hex digest
        requires the key to exist with exactly that digest. Content type and
        other keys are not compared.
        """
        self._check_key(key)
        if not isinstance(payload, (bytes, bytearray, memoryview)):
            raise ObjectStoreError("payload must be bytes")
        if content_type is not None and not isinstance(content_type, str):
            raise ObjectStoreError("content_type must be a string or None")
        expected = self._check_precondition(expected_sha256)
        data = bytes(payload)
        sha = hashlib.sha256(data).hexdigest()
        entry = {"sha256": sha, "size": len(data), "content_type": content_type}
        with self._lock:
            if expected is not _MISSING and not self._precondition_met(key, expected):
                raise ObjectStoreError("precondition failed")
            self._store_blob(sha, data)
            self._index["objects"][key] = entry
            self._save_index()
            return dict(entry)

    def _store_blob(self, sha, data):
        """Write the blob for *sha* when missing and repair it when corrupted.

        An existing file is hashed on every put. Intact files are left exactly
        as they are so dedup costs nothing extra; a file whose digest no longer
        matches is rewritten atomically from the complete *data*, so an
        interrupted repair leaves either the old bytes or the full new bytes.
        """
        path = os.path.join(self.blobs_dir, sha)
        if os.path.exists(path):
            try:
                with open(path, "rb") as handle:
                    stored = handle.read()
            except FileNotFoundError:
                stored = None
            except OSError:
                raise ObjectStoreError("blob io error")
            if stored is not None:
                if hashlib.sha256(stored).hexdigest() == sha:
                    return
                try:
                    _atomic_write(path, data)
                except OSError:
                    raise ObjectStoreError("blob io error")
                return
        try:
            _atomic_write(path, data)
        except OSError:
            raise ObjectStoreError("blob io error")

    def get(self, key):
        """Return ``(payload, entry)`` for *key*."""
        with self._lock:
            entry = self.head(key)
            data = self.blob(entry["sha256"])
            if len(data) != entry["size"]:
                raise ObjectStoreError("corrupted blob")
            return data, entry

    def head(self, key):
        """Return a copy of the metadata entry for *key*."""
        self._check_key(key)
        with self._lock:
            entry = self._index["objects"].get(key)
            if entry is None:
                raise ObjectStoreError("not found: %s" % (key,))
            return dict(entry)

    def delete(self, key, expected_sha256=_MISSING):
        """Drop *key*; shared blobs stay on disk for the keys still using them.

        With *expected_sha256*, deletion also requires the key's current
        digest to match (or an explicit ``None`` requires the key absent); a
        satisfied absent-condition delete still reports the key as not found.
        """
        self._check_key(key)
        expected = self._check_precondition(expected_sha256)
        with self._lock:
            if key not in self._index["objects"]:
                raise ObjectStoreError("not found: %s" % (key,))
            if expected is not _MISSING and not self._precondition_met(key, expected):
                raise ObjectStoreError("precondition failed")
            del self._index["objects"][key]
            self._save_index()

    def blob(self, sha256):
        """Return the raw bytes stored under digest *sha256*.

        The digest of the bytes actually on disk is recomputed on every read,
        so truncation, appended bytes and same-length tampering are all
        rejected instead of being handed back to the caller.
        """
        self._require_sha(sha256)
        with self._lock:
            try:
                with open(os.path.join(self.blobs_dir, sha256), "rb") as handle:
                    data = handle.read()
            except FileNotFoundError:
                raise ObjectStoreError("not found: blob %s" % (sha256,))
            except OSError:
                raise ObjectStoreError("blob io error")
            if hashlib.sha256(data).hexdigest() != sha256:
                raise ObjectStoreError("corrupted blob")
            return data

    def blob_digests(self):
        """Return the sorted digests currently present in the blob directory."""
        with self._lock:
            return sorted(name for name in os.listdir(self.blobs_dir) if _is_sha256(name))

    # -- resumable uploads ----------------------------------------------
    def _session_meta_path(self, session_id):
        return os.path.join(self.uploads_dir, session_id + ".json")

    def _session_part_path(self, session_id):
        return os.path.join(self.uploads_dir, session_id + ".part")

    def _load_uploads(self):
